mapper.select:
SELECT COUNT(*)
FROM admin_logs al
LEFT JOIN users u ON al.admin_id = u.id


        AND (
            u.name LIKE CONCAT('%', #{search}, '%') OR
            al.action_type LIKE CONCAT('%', #{search}, '%') OR
            al.description LIKE CONCAT('%', #{search}, '%') OR
            al.ip_address LIKE CONCAT('%', #{search}, '%')
        )


        AND al.action_type = #{actionType}


        AND al.log_level = #{logLevel}


        AND DATE(al.created_at) >= #{dateFrom}


        AND DATE(al.created_at) <= #{dateTo}

SELECT al.id, al.admin_id, u.name as admin_name, al.action_type, al.target_table, al.target_id, al.log_level, al.is_successful, al.http_method, al.request_uri, al.before_value, al.after_value, al.description, al.ip_address, al.user_agent, al.created_at FROM admin_logs al LEFT JOIN users u ON al.admin_id = u.id
AND ( u.name LIKE CONCAT('%', #{search}, '%') OR al.action_type LIKE CONCAT('%', #{search}, '%') OR al.description LIKE CONCAT('%', #{search}, '%') OR al.ip_address LIKE CONCAT('%', #{search}, '%') )
AND al.action_type = #{actionType}
AND al.log_level = #{logLevel}
AND DATE(al.created_at) >= #{dateFrom}
AND DATE(al.created_at) <= #{dateTo}
ORDER BY al.created_at ASC
ORDER BY al.action_type ASC, al.created_at DESC
ORDER BY u.name ASC, al.created_at DESC
ORDER BY al.log_level ASC, al.created_at DESC
ORDER BY al.created_at DESC
LIMIT #{offset}, #{limit}

SELECT action_type as actionType, COUNT(*) as count, SUM(CASE WHEN is_successful = true THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN is_successful = false THEN 1 ELSE 0 END) as failureCount FROM admin_logs
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY action_type ORDER BY count DESC

SELECT al.admin_id as adminId, u.name as adminName, COUNT(*) as totalCount, SUM(CASE WHEN al.is_successful = true THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN al.is_successful = false THEN 1 ELSE 0 END) as failureCount, MAX(al.created_at) as lastActivity FROM admin_logs al LEFT JOIN users u ON al.admin_id = u.id
AND DATE(al.created_at) >= #{dateFrom}
AND DATE(al.created_at) <= #{dateTo}
GROUP BY al.admin_id, u.name ORDER BY totalCount DESC

SELECT DATE(created_at) as logDate, COUNT(*) as totalCount, SUM(CASE WHEN is_successful = true THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN is_successful = false THEN 1 ELSE 0 END) as failureCount, COUNT(DISTINCT admin_id) as activeAdminCount FROM admin_logs
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY DATE(created_at) ORDER BY logDate DESC

SELECT log_level as logLevel, COUNT(*) as count FROM admin_logs
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY log_level ORDER BY CASE log_level WHEN 'CRITICAL' THEN 1 WHEN 'ERROR' THEN 2 WHEN 'WARN' THEN 3 WHEN 'INFO' THEN 4 ELSE 5 END

SELECT al.id, al.admin_id, u.name as admin_name, al.action_type, al.target_table, al.target_id, al.log_level, al.is_successful, al.http_method, al.request_uri, al.before_value, al.after_value, al.description, al.ip_address, al.user_agent, al.created_at FROM admin_logs al LEFT JOIN users u ON al.admin_id = u.id WHERE al.is_successful = false
AND DATE(al.created_at) >= #{dateFrom}
AND DATE(al.created_at) <= #{dateTo}
ORDER BY al.created_at DESC LIMIT #{offset}, #{limit}

SELECT al.id, al.admin_id, u.name as admin_name, al.action_type, al.target_table, al.target_id, al.log_level, al.is_successful, al.http_method, al.request_uri, al.before_value, al.after_value, al.description, al.ip_address, al.user_agent, al.created_at FROM admin_logs al LEFT JOIN users u ON al.admin_id = u.id WHERE al.target_table = #{targetTable}
AND al.target_id = #{targetId}
ORDER BY al.created_at DESC
